def _load_catalog() -> list[dict[str, Any]]:
    catalog_path = Path(__file__).parent / "data" / "model_catalog.yaml"
    with open(catalog_path) as f:
        return yaml.safe_load(f) or []


def _to_model_info(entry: dict[str, Any]) -> ModelInfo:
    caps_raw = entry.get("capabilities", {})
    return ModelInfo(
        name=entry["name"],
        backend=entry["backend"],
        size_gb=float(entry.get("size_gb", 0)),
        min_vram_mb=int(entry.get("min_vram_mb", 0)),
        recommended_vram_mb=int(entry.get("recommended_vram_mb", 0)),
        capabilities=EngineCapabilities(
            chat=caps_raw.get("chat", False),
            embeddings=caps_raw.get("embeddings", False),
            tool_calling=caps_raw.get("tool_calling", False),
            vision=caps_raw.get("vision", False),
        ),
        quantization=entry.get("quantization"),
    )


# ---------------------------------------------------------------------------
# ModelRegistry
# ---------------------------------------------------------------------------


class ModelRegistry:
    """
    Enumerate and recommend models.

    All Ollama I/O is via raw urllib — no ollama package required.
    VRAM requirements come from model_catalog.yaml (not the Ollama API).
    """

    def __init__(self, ollama_host: str = _OLLAMA_BASE) -> None:
        self.ollama_host = ollama_host
        self._catalog: dict[str, dict[str, Any]] = {e["name"]: e for e in _load_catalog()}

    def list_available_models(self, backend: str = "ollama") -> list[str]:
        if backend == "ollama":
            if not check_ollama_running(self.ollama_host):
                raise BackendUnavailableError(f"Ollama not reachable at {self.ollama_host}.")
            return sorted(m.name for m in list_ollama_models(self.ollama_host))
        return sorted(n for n, e in self._catalog.items() if e.get("backend") == backend)

    def get_model_info(self, model: str, backend: str = "ollama") -> ModelInfo:
        # 1. Exact match
        entry = self._catalog.get(model)
        if entry:
            return _to_model_info(entry)

        # 2. Match base:tag — e.g. "qwen3:32b" matches catalog key "qwen3:32b"
        #    (already covered by exact match above, but belt-and-suspenders)

        # 3. Prefix match only when no tag specified — e.g. "qwen3" → "qwen3:8b"
        #    Do NOT prefix-match when a tag is specified, to avoid qwen3:32b → qwen3:8b
        if ":" not in model:
            base = model
            entry = next(
                (
                    e
                    for n, e in self._catalog.items()
                    if e.get("backend") == backend and n.startswith(base + ":")
                ),
                None,
            )
            if entry:
                return _to_model_info(entry)

        raise ModelNotFoundError(f"Model '{model}' not found for backend='{backend}'.")

    def recommend_model(
        self,
        task: TaskType,
        hardware: HardwareProfile,
        backend: str = "ollama",
        prefer_speed: bool = False,
    ) -> str:
        try:
            available: set[str] | None = set(self.list_available_models(backend))
        except BackendUnavailableError:
            available = None  # catalog-only fallback

        candidates: list[ModelInfo] = []
        for name, entry in self._catalog.items():
            if entry.get("backend") != backend:
                continue
            if task not in entry.get("tasks", []):
                continue
            caps = entry.get("capabilities", {})
            if task == "embeddings" and not caps.get("embeddings"):
                continue
            if available is not None and name not in available:
                continue
            info = _to_model_info(entry)
            vram_needed = info.min_vram_mb if hardware.is_cpu_only else info.recommended_vram_mb
            if vram_needed <= hardware.vram_total_mb or hardware.is_cpu_only:
                candidates.append(info)

        if not candidates:
            raise ModelNotFoundError(
                f"No model fits task='{task}', backend='{backend}', "
                f"vram={hardware.vram_total_mb}MB."
            )
        candidates.sort(key=lambda m: m.recommended_vram_mb, reverse=not prefer_speed)
        return candidates[0].name

    def download_model(
        self,
        model: str,
        backend: str = "ollama",
        progress_callback: Callable[[float, float, float], None] | None = None,
    ) -> bool:
        if backend != "ollama":
            raise NotImplementedError(f"download_model not implemented for '{backend}'")
        return pull_ollama_model(model, progress_callback, self.ollama_host)

"""
llm_engines/factory.py

EngineFactory: construct engines and failover profiles from config.

Supports two YAML formats:

1. Single engine (minimal):
       backend: ollama
       model: qwen3:27b
       options:
         keep_alive: 0

2. Multi-engine profile (from Engram's llm_engines.yaml):
       engines:
         qwen27b:
           type: ollama
           model: qwen3:27b
           base_url: http://localhost:11434
           num_gpu: null
           max_context: 32768
         qwen8b:
           type: ollama
           model: qwen3:8b
       profiles:
         default_local:
           engines: [qwen27b, qwen8b]
           allow_cloud_failover: false
           max_attempts: 4
           circuit_breaker_failures: 3
           circuit_breaker_cooldown_s: 30

Config resolution order (matching Engram):
  1. Explicit path argument
  2. ~/.engram/llm_engines.yaml  (user config)
  3. llm_engines/data/llm_engines.yaml  (packaged default)
"""

from __future__ import annotations

import importlib
import logging
import os
import shutil
from pathlib import Path
from typing import Any, cast

import yaml

from llm_engines.contracts import (
    ChatModel,
    EngineConfigError,
)
from llm_engines.router import FailoverEngine, FailoverPolicy

logger = logging.getLogger(__name__)

_PACKAGED_DEFAULT = Path(__file__).parent / "data" / "llm_engines.yaml"
_USER_CONFIG = Path("~/.engram/llm_engines.yaml").expanduser()

# Lazy-import map: backend name → dotted class path
_BACKEND_MAP: dict[str, str] = {
    "ollama": "llm_engines.backends.ollama.OllamaEngine",
    "anthropic": "llm_engines.backends.anthropic.AnthropicEngine",
    "openai": "llm_engines.backends.openai.OpenAIEngine",
    "vllm": "llm_engines.backends.vllm.vLLMEngine",
    "llamacpp": "llm_engines.backends.llamacpp.LlamaCppEngine",
    "llama_cpp": "llm_engines.backends.llamacpp.LlamaCppEngine",
    "mock": "llm_engines.backends.mock.MockEngine",
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _import_class(dotted: str) -> type:
    module_path, class_name = dotted.rsplit(".", 1)
    module = importlib.import_module(module_path)
    return cast(type, getattr(module, class_name))


def _load_config(config_path: str | Path | None = None) -> dict[str, Any]:
    """Load YAML config. Resolution: explicit → user → packaged default."""
    if config_path:
        path = Path(config_path).expanduser()
    elif _USER_CONFIG.exists():
        path = _USER_CONFIG
    elif _PACKAGED_DEFAULT.exists():
        path = _PACKAGED_DEFAULT
    else:
        return {}

    if not path.exists():
        raise EngineConfigError(f"Config file not found: {path}")

    try:
        return yaml.safe_load(path.read_text()) or {}
    except yaml.YAMLError as e:
        raise EngineConfigError(f"Invalid YAML in {path}: {e}") from e


def _ensure_user_config() -> Path:
    """Copy packaged default to ~/.engram/ if no user config exists."""
    if not _USER_CONFIG.exists() and _PACKAGED_DEFAULT.exists():
        _USER_CONFIG.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(_PACKAGED_DEFAULT, _USER_CONFIG)
    return _USER_CONFIG


# ---------------------------------------------------------------------------
# Single-engine construction
# ---------------------------------------------------------------------------


def _engine_from_config_dict(
    engine_cfg: dict[str, Any],
    engine_name: str = "<inline>",
) -> ChatModel:
    """
    Build one engine from a config dict.

    Accepts both flat format (backend/model keys) and named-engine format
    (type/model keys, matching Engram's llm_engines.yaml).
    """
    # Normalise key names
    backend = engine_cfg.get("type") or engine_cfg.get("backend")
    if not backend:
        raise EngineConfigError(f"Engine '{engine_name}' must specify 'type' (or 'backend').")
    backend = backend.lower()

    if backend not in _BACKEND_MAP:
        raise EngineConfigError(
            f"Unknown backend '{backend}' in engine '{engine_name}'. "
            f"Available: {sorted(_BACKEND_MAP)}"
        )

    try:
        engine_cls = _import_class(_BACKEND_MAP[backend])
    except ImportError as e:
        raise EngineConfigError(
            f"Backend '{backend}' is not installed. "
            f"Install with: pip install llm-engines[{backend}]"
        ) from e

    # Build kwargs from config, passing only what the constructor accepts
    kwargs: dict[str, Any] = {}

    model = engine_cfg.get("model")
    if model:
        kwargs["model"] = model

    # Ollama-specific
    if backend == "ollama":
        if "base_url" in engine_cfg:
            kwargs["host"] = engine_cfg["base_url"].rstrip("/v1").rstrip("/")
        if "num_gpu" in engine_cfg and engine_cfg["num_gpu"] is not None:
            kwargs["num_gpu"] = int(engine_cfg["num_gpu"])
        if "thinking" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["thinking"])
        if "keep_alive" in engine_cfg:
            kwargs["keep_alive"] = int(engine_cfg["keep_alive"])
        if bool(engine_cfg.get("auto_pull", False)):
            kwargs["auto_pull"] = True

    # Cloud engines
    if backend in ("anthropic", "openai"):
        api_key_env = engine_cfg.get("api_key_env")
        if api_key_env:
            kwargs["api_key"] = os.getenv(api_key_env)
        elif "api_key" in engine_cfg:
            kwargs["api_key"] = engine_cfg["api_key"]
        if "base_url" in engine_cfg:
            kwargs["base_url"] = engine_cfg["base_url"]
        if "is_cloud" in engine_cfg:
            kwargs["is_cloud"] = bool(engine_cfg["is_cloud"])
        if "timeout" in engine_cfg and engine_cfg["timeout"] is not None:
            kwargs["timeout"] = float(engine_cfg["timeout"])
        if "debug" in engine_cfg:
            kwargs["debug"] = bool(engine_cfg["debug"])
        if backend == "openai" and "supports_embeddings" in engine_cfg:
            kwargs["supports_embeddings"] = bool(engine_cfg["supports_embeddings"])

    # vLLM HTTP server
    if backend == "vllm":
        if "base_url" in engine_cfg:
            kwargs["base_url"] = str(engine_cfg["base_url"])
        if "max_context" in engine_cfg and engine_cfg["max_context"] is not None:
            kwargs["max_context"] = int(engine_cfg["max_context"])
        if "timeout" in engine_cfg and engine_cfg["timeout"] is not None:
            kwargs["timeout"] = float(engine_cfg["timeout"])
        if "debug" in engine_cfg:
            kwargs["debug"] = bool(engine_cfg["debug"])

    # llama.cpp (in-process via llama-cpp-python)
    if backend in ("llamacpp", "llama_cpp"):
        # Generic "model" arg maps to LlamaCppEngine's model_path. Accept
        # "gguf_path" as a config-file alias for the same thing.
        if "model" in kwargs:
            kwargs["model_path"] = kwargs.pop("model")
        if "gguf_path" in engine_cfg:
            kwargs["model_path"] = engine_cfg["gguf_path"]
        # base_url doesn't apply to in-process llama.cpp; drop silently if set.
        kwargs.pop("base_url", None)
        # Pass through LlamaCppEngine.__init__ kwargs, coercing types so YAML
        # string values work the same as Python ints/bools.
        for kw in ("n_gpu_layers", "n_ctx", "n_threads", "n_batch", "n_ubatch"):
            if kw in engine_cfg and engine_cfg[kw] is not None:
                kwargs[kw] = int(engine_cfg[kw])
        for kw in ("cache_type_k", "cache_type_v"):
            if kw in engine_cfg and engine_cfg[kw] is not None:
                kwargs[kw] = str(engine_cfg[kw])
        if "thinking" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["thinking"])
        if "think" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["think"])
        for kw in ("flash_attn", "verbose", "embedding"):
            if kw in engine_cfg:
                kwargs[kw] = bool(engine_cfg[kw])

    # Pass-through options
    options = engine_cfg.get("options", {})
    if options:
        kwargs["options"] = options

    try:
        return cast(ChatModel, engine_cls(**kwargs))
    except TypeError as e:
        raise EngineConfigError(
            f"Invalid arguments for backend '{backend}' in engine '{engine_name}': {e}"
        ) from e


# ---------------------------------------------------------------------------
# EngineFactory
# ---------------------------------------------------------------------------


class EngineFactory:
    """
    Create engine instances from config.

    Three usage patterns:

    1. Programmatic single engine:
           engine = EngineFactory.create("ollama", model="qwen3:8b")

    2. From simple YAML file:
           engine = EngineFactory.from_config("myconfig.yaml")

    3. From Engram-format YAML profile:
           engine = EngineFactory.from_profile("default_local", "llm_engines.yaml")
    """

    @classmethod
    def _import_backend(cls, backend: str) -> type:
        """Import and return the engine class for a backend name."""
        backend = backend.lower()
        if backend not in _BACKEND_MAP:
            raise EngineConfigError(
                f"Unknown backend '{backend}'. Available: {sorted(_BACKEND_MAP)}"
            )
        return _import_class(_BACKEND_MAP[backend])

    @classmethod
    def create(cls, backend: str, **kwargs: Any) -> ChatModel:
        """
        Instantiate a single engine by backend name.

        Args:
            backend: "ollama" | "anthropic" | "openai" | "vllm" |
                     "llamacpp" | "mock"
            **kwargs: Passed to the engine constructor.

        Raises:
            EngineConfigError
        """
        cfg = {"type": backend, **kwargs}
        return _engine_from_config_dict(cfg, backend)

    @classmethod
    def from_config(cls, config_path: str | Path) -> ChatModel:
        """
        Build a single engine from a simple YAML file.

        YAML format:
            backend: ollama      # or 'type: ollama'
            model: qwen3:8b
            options:
              keep_alive: 0
        """
        config = _load_config(config_path)

        # Simple flat format: has 'backend' or 'type' at top level
        if "backend" in config or "type" in config:
            return _engine_from_config_dict(config, str(config_path))

        raise EngineConfigError(
            f"{config_path}: expected top-level 'backend'/'type' key for single-engine "
            "format, or use from_profile() for multi-engine YAML."
        )

    @classmethod
    def from_profile(
        cls,
        profile_name: str = "default_local",
        config_path: str | Path | None = None,
        override_engines: list[str] | None = None,
        override_allow_cloud: bool | None = None,
    ) -> FailoverEngine:
        """
        Build a FailoverEngine from a named profile in a YAML config.

        Args:
            profile_name:         Key in the 'profiles' section.
            config_path:          Optional explicit path. Falls back to
                                  ~/.engram/llm_engines.yaml, then packaged default.
            override_engines:     Replace the engine list from the profile.
            override_allow_cloud: Override allow_cloud_failover.

        Returns:
            FailoverEngine (implements ChatModel).

        Raises:
            EngineConfigError
        """
        config = _load_config(config_path)

        profiles = config.get("profiles") or {}
        if profile_name not in profiles:
            available = sorted(profiles)
            raise EngineConfigError(f"Profile '{profile_name}' not found. Available: {available}")

        profile = profiles[profile_name] or {}
        engines_cfg = config.get("engines") or {}

        engine_names: list[str] = override_engines or list(profile.get("engines") or [])
        if not engine_names:
            raise EngineConfigError(f"Profile '{profile_name}' must list at least one engine.")

        engines: list[ChatModel] = []
        for name in engine_names:
            if name not in engines_cfg:
                available = sorted(engines_cfg)
                raise EngineConfigError(
                    f"Engine '{name}' (referenced in profile '{profile_name}') "
                    f"not found in 'engines' section. Available: {available}"
                )
            engine = _engine_from_config_dict(engines_cfg[name], name)
            engines.append(engine)
            logger.debug("Loaded engine '%s' for profile '%s'", name, profile_name)

        allow_cloud = (
            override_allow_cloud
            if override_allow_cloud is not None
            else bool(profile.get("allow_cloud_failover", False))
        )
        policy = FailoverPolicy(
            max_attempts=int(profile.get("max_attempts", 4)),
            allow_cloud_failover=allow_cloud,
            cloud_policy=str(profile.get("cloud_policy", "query_plus_summary")),
            circuit_breaker_failures=int(profile.get("circuit_breaker_failures", 3)),
            circuit_breaker_cooldown_s=float(profile.get("circuit_breaker_cooldown_s", 30.0)),
        )
        return FailoverEngine(engines=engines, policy=policy, name=profile_name)

    @classmethod
    def from_engine_name(
        cls,
        engine_name: str,
        config_path: str | Path | None = None,
    ) -> ChatModel:
        """
        Build a single engine by its named entry in the 'engines' section.

        Compatible with Engram's create_engine() calling convention.
        """
        config = _load_config(config_path)
        engines_cfg = config.get("engines") or {}
        if engine_name not in engines_cfg:
            available = sorted(engines_cfg)
            raise EngineConfigError(f"Engine '{engine_name}' not found. Available: {available}")
        return _engine_from_config_dict(engines_cfg[engine_name], engine_name)

    @classmethod
    def register_backend(cls, name: str, dotted_class_path: str) -> None:
        """Register a custom backend for use in create() and YAML configs."""
        _BACKEND_MAP[name.lower()] = dotted_class_path

"""
llm_engines/backends/vllm.py

vLLMEngine: high-performance local inference via vLLM's OpenAI-compatible API.

Protocols: ChatModel, ToolCallingModel, AsyncStreamingModel, BatchChatModel, LogprobModel
is_cloud = False (local server, no sanitisation applied by FailoverEngine)

Requires: a running vLLM server — NOT the vllm Python package directly.
vLLM is invoked as a server process; this engine talks to it over HTTP
using the openai package as the client.

Typical startup:
    vllm serve Qwen/Qwen2.5-32B-Instruct-AWQ \
        --port 8000 \
        --gpu-memory-utilization 0.92 \
        --max-model-len 8192

Requires: pip install llm-engines[openai]  (uses openai client against vLLM)

Key differences from OpenAIEngine:
  - No API key required (passes "dummy")
  - Logprobs available via the OpenAI-compat /v1/chat/completions endpoint
  - Model name is resolved at startup against /v1/models (vLLM reports its
    own model ID which may differ from what you specify in YAML)
  - Batch generation supported via multiple parallel async calls
  - is_cloud = False → FailoverEngine does not strip memory context
"""

from __future__ import annotations

import asyncio
import json
import logging
import time
from typing import Any, AsyncIterator

from llm_engines.contracts import (
    BackendUnavailableError,
    ChatMessage,
    ContextLengthExceededError,
    EngineCapabilities,
    EngineConfigError,
    GenerationError,
    GenerationRequest,
    GenerationResponse,
    LogprobResult,
    TokenLogprob,
    ToolCall,
    ToolSpec,
    UsageStats,
)

try:
    import openai as _openai
except ImportError as _e:
    raise ImportError(
        "vLLMEngine uses the 'openai' package to communicate with vLLM's HTTP API. "
        "Install with: pip install llm-engines[openai]"
    ) from _e

logger = logging.getLogger(__name__)

BACKEND = "vllm"

_FINISH_MAP = {
    "stop": "stop",
    "length": "length",
    "tool_calls": "tool_call",
}


def _map_finish(raw: str | None) -> str:
    if raw is None:
        return "unknown"
    return _FINISH_MAP.get(raw, "unknown")


def _to_openai_messages(request: GenerationRequest) -> list[dict[str, Any]]:
    messages: list[dict[str, Any]] = []
    for message in request.messages:
        if message.role == "tool":
            messages.append(
                {
                    "role": "tool",
                    "tool_call_id": message.tool_call_id or "",
                    "content": message.content or "",
                }
            )
        elif message.role == "assistant" and message.tool_calls:
            messages.append(
                {
                    "role": "assistant",
                    "content": message.content,
                    "tool_calls": [
                        {
                            "id": call.call_id,
                            "type": "function",
                            "function": {
                                "name": call.name,
                                "arguments": json.dumps(call.arguments),
                            },
                        }
                        for call in message.tool_calls
                    ],
                }
            )
        else:
            messages.append({"role": message.role, "content": message.content or ""})
    return messages


def _extract_tool_calls(choice: Any) -> list[ToolCall]:
    calls: list[ToolCall] = []
    for raw_call in getattr(choice.message, "tool_calls", None) or []:
        try:
            arguments = json.loads(raw_call.function.arguments)
        except (TypeError, ValueError):
            arguments = {"raw": raw_call.function.arguments}
        calls.append(
            ToolCall(
                call_id=raw_call.id,
                name=raw_call.function.name,
                arguments=arguments,
            )
        )
    return calls


def _apply_thinking_preference(kwargs: dict[str, Any], request: GenerationRequest) -> None:
    if request.thinking is not None:
        kwargs["extra_body"] = {"chat_template_kwargs": {"enable_thinking": request.thinking}}


def _apply_seed_preference(kwargs: dict[str, Any], request: GenerationRequest) -> None:
    if request.seed is not None:
        kwargs["seed"] = request.seed


class vLLMEngine:
    """
    LLM engine backed by a local vLLM HTTP server.

    Args:
        model:          Model name to request. vLLM may return a different
                        resolved name — check model_name in responses.
        base_url:       vLLM server URL, e.g. "http://localhost:8000/v1".
        max_context:    Maximum context length. vLLM enforces its own limit;
                        this is used for client-side truncation decisions.
        timeout:        Request timeout in seconds.
        debug:          Preserve raw provider payload in responses.
    """

    is_cloud: bool = False

    def __init__(
        self,
        model: str,
        base_url: str = "http://localhost:8000/v1",
        max_context: int = 8192,
        timeout: float = 120.0,
        debug: bool = False,
    ) -> None:
        self.model = model
        self.base_url = base_url.rstrip("/")
        self.max_context = max_context
        self.debug = debug

        try:
            self._client = _openai.OpenAI(
                api_key="dummy",
                base_url=self.base_url,
                timeout=timeout,
            )
            self._async_client = _openai.AsyncOpenAI(
                api_key="dummy",
                base_url=self.base_url,
                timeout=timeout,
            )
        except Exception as e:
            raise EngineConfigError(f"Failed to create vLLM client: {e}") from e

        self._resolved_model = self._resolve_model()

    def _resolve_model(self) -> str:
        """
        Query /v1/models and resolve the best match for self.model.

        vLLM exposes the model under its HuggingFace ID, which may differ
        from a short alias. Returns the resolved ID, or self.model if
        the server is unreachable (allowing deferred connection).
        """
        try:
            models = self._client.models.list()
            ids = [m.id for m in models.data]
            if not ids:
                return self.model
            # Exact match
            if self.model in ids:
                return self.model
            # Suffix match: "Qwen2.5-32B-Instruct-AWQ" matches "Qwen/Qwen2.5-32B-Instruct-AWQ"
            for model_id in ids:
                if model_id.endswith(self.model) or self.model in model_id:
                    logger.info("vLLM model resolved: '%s' → '%s'", self.model, model_id)
                    return model_id
            # Fallback: use first available
            logger.warning(
                "vLLM: requested model '%s' not found. Using '%s'. Available: %s",
                self.model,
                ids[0],
                ids,
            )
            return ids[0]
        except Exception as e:
            logger.warning("vLLM model discovery failed (%s) — using '%s'", e, self.model)
            return self.model

    # ------------------------------------------------------------------
    # ChatModel Protocol
    # ------------------------------------------------------------------

    def get_capabilities(self) -> EngineCapabilities:
        return EngineCapabilities(
            chat=True,
            streaming=False,
            async_streaming=True,
            tool_calling=True,
            embeddings=False,  # vLLM can serve embedding models separately
            structured_output=False,
            batch_generation=True,
            vision=False,
            usage_reporting=True,
            logprobs=True,
        )

    def generate(self, request: GenerationRequest) -> GenerationResponse:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages: Any = _to_openai_messages(request)
        kwargs: dict[str, Any] = {
            "model": self._resolved_model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
        }
        if request.stop:
            kwargs["stop"] = request.stop
        _apply_thinking_preference(kwargs, request)
        _apply_seed_preference(kwargs, request)

        t0 = time.perf_counter()
        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(
                f"vLLM not reachable at {self.base_url}. Is vLLM running?"
            ) from e
        except _openai.BadRequestError as e:
            msg = str(e).lower()
            if "max_model_len" in msg or "too long" in msg or "context" in msg:
                raise ContextLengthExceededError(str(e)) from e
            raise GenerationError(f"vLLM bad request: {e}") from e
        except Exception as e:
            raise GenerationError(f"vLLM generation failed: {e}") from e

        latency_ms = (time.perf_counter() - t0) * 1000
        return self._build_response(raw, latency_ms, request=request)

    def _build_response(
        self, raw: Any, latency_ms: float, *, request: GenerationRequest
    ) -> GenerationResponse:
        choice = raw.choices[0]
        u = getattr(raw, "usage", None)
        usage = UsageStats(
            input_tokens=getattr(u, "prompt_tokens", None),
            output_tokens=getattr(u, "completion_tokens", None),
            total_tokens=getattr(u, "total_tokens", None),
            latency_ms=round(latency_ms, 3),
        )
        return GenerationResponse(
            message=ChatMessage(
                role="assistant",
                content=choice.message.content,
                tool_calls=_extract_tool_calls(choice),
            ),
            finish_reason=_map_finish(choice.finish_reason),  # type: ignore[arg-type]
            usage=usage,
            model_name=getattr(raw, "model", self._resolved_model),
            backend=BACKEND,
            raw_provider_payload=({"id": raw.id, "model": raw.model} if self.debug else None),
            seed_status="accepted" if request.seed is not None else "not_requested",
        )

    # ------------------------------------------------------------------
    # ToolCallingModel Protocol
    # ------------------------------------------------------------------

    def generate_with_tools(
        self,
        request: GenerationRequest,
        available_tools: list[ToolSpec],
    ) -> GenerationResponse:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        kwargs: dict[str, Any] = {
            "model": self._resolved_model,
            "messages": _to_openai_messages(request),
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "tools": [tool.to_openai_schema() for tool in available_tools],
            "tool_choice": "auto",
        }
        if request.stop:
            kwargs["stop"] = request.stop
        _apply_thinking_preference(kwargs, request)
        _apply_seed_preference(kwargs, request)

        started = time.perf_counter()
        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.APIConnectionError as exc:
            raise BackendUnavailableError(
                f"vLLM not reachable at {self.base_url}. Is vLLM running?"
            ) from exc
        except _openai.BadRequestError as exc:
            message = str(exc).lower()
            if "max_model_len" in message or "too long" in message or "context" in message:
                raise ContextLengthExceededError(str(exc)) from exc
            raise GenerationError(f"vLLM tool request rejected: {exc}") from exc
        except Exception as exc:
            raise GenerationError(f"vLLM tool generation failed: {exc}") from exc

        return self._build_response(raw, (time.perf_counter() - started) * 1000, request=request)

    # ------------------------------------------------------------------
    # LogprobModel Protocol
    # ------------------------------------------------------------------

    def generate_with_logprobs(
        self,
        request: GenerationRequest,
        top_logprobs: int = 0,
    ) -> LogprobResult:
        """Generate with token logprobs. Used by Engram's RTRL surprise filter."""
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages: Any = _to_openai_messages(request)
        actual_top = max(1, top_logprobs)

        kwargs: dict[str, Any] = {
            "model": self._resolved_model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "logprobs": True,
            "top_logprobs": actual_top,
        }
        _apply_thinking_preference(kwargs, request)
        _apply_seed_preference(kwargs, request)

        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"vLLM unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"vLLM logprob generation failed: {e}") from e

        choice = raw.choices[0]
        text = choice.message.content or ""
        token_logprobs: list[TokenLogprob] = []

        if choice.logprobs and choice.logprobs.content:
            for tlp in choice.logprobs.content:
                token_logprobs.append(
                    TokenLogprob(
                        token=tlp.token,
                        logprob=tlp.logprob,
                        bytes=getattr(tlp, "bytes", None),
                    )
                )

        return LogprobResult(text=text, token_logprobs=token_logprobs)

    # ------------------------------------------------------------------
    # AsyncStreamingModel Protocol
    # ------------------------------------------------------------------

    async def stream_async(self, request: GenerationRequest) -> AsyncIterator[str]:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages: Any = _to_openai_messages(request)
        kwargs: dict[str, Any] = {
            "model": self._resolved_model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "stream": True,
        }
        _apply_thinking_preference(kwargs, request)
        _apply_seed_preference(kwargs, request)
        try:
            stream: Any = await self._async_client.chat.completions.create(**kwargs)
            async for chunk in stream:
                if chunk.choices:
                    delta = chunk.choices[0].delta.content
                    if delta:
                        yield delta
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"vLLM unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"vLLM streaming failed: {e}") from e

    # ------------------------------------------------------------------
    # BatchChatModel Protocol
    # ------------------------------------------------------------------

    def generate_batch(
        self,
        requests: list[GenerationRequest],
    ) -> list[GenerationResponse]:
        """
        Process multiple requests in parallel via asyncio.

        vLLM handles concurrent requests efficiently through continuous batching.
        This method fans out all requests simultaneously rather than serially.
        """

        async def _run_all() -> list[GenerationResponse]:
            tasks = [self._generate_async(req) for req in requests]
            return await asyncio.gather(*tasks)

        async def _ensure_loop() -> list[GenerationResponse]:
            return await _run_all()

        try:
            loop = asyncio.get_event_loop()
            if loop.is_running():
                # Already in an async context — use nest_asyncio or thread pool
                import concurrent.futures

                with concurrent.futures.ThreadPoolExecutor() as pool:
                    future = pool.submit(asyncio.run, _run_all())
                    return future.result()
            return loop.run_until_complete(_run_all())
        except Exception:
            return asyncio.run(_run_all())

    async def _generate_async(self, request: GenerationRequest) -> GenerationResponse:
        messages: Any = _to_openai_messages(request)
        kwargs: dict[str, Any] = {
            "model": self._resolved_model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
        }
        _apply_thinking_preference(kwargs, request)
        _apply_seed_preference(kwargs, request)
        t0 = time.perf_counter()
        try:
            raw = await self._async_client.chat.completions.create(**kwargs)
        except Exception as e:
            raise GenerationError(f"vLLM async generation failed: {e}") from e
        return self._build_response(raw, (time.perf_counter() - t0) * 1000, request=request)

"""
llm_engines/backends/anthropic.py

AnthropicEngine: cloud inference via the Anthropic API.

Protocols implemented: ChatModel, ToolCallingModel, AsyncStreamingModel
Embeddings: not supported (Anthropic has no native embedding endpoint)
Sync streaming: not implemented (use stream_async for FastAPI/asyncio)

Requires: pip install llm-engines[anthropic]
API key: ANTHROPIC_API_KEY env var (or pass api_key= directly)

Privacy note: is_cloud = True — FailoverEngine will apply cloud_policy
(memory block sanitisation) before routing to this engine.
"""

from __future__ import annotations

import logging
import os
import time
from typing import Any, AsyncIterator

from llm_engines.contracts import (
    BackendUnavailableError,
    ChatMessage,
    EngineCapabilities,
    EngineConfigError,
    GenerationError,
    GenerationRequest,
    GenerationResponse,
    RateLimitError,
    ContextLengthExceededError,
    ToolCall,
    ToolSpec,
    UsageStats,
)

try:
    import anthropic as _anthropic
except ImportError as _e:
    raise ImportError(
        "AnthropicEngine requires the 'anthropic' package. "
        "Install with: pip install llm-engines[anthropic]"
    ) from _e

logger = logging.getLogger(__name__)

BACKEND = "anthropic"

# Map Anthropic stop_reason → canonical FinishReason
_FINISH_MAP: dict[str, str] = {
    "end_turn": "stop",
    "max_tokens": "length",
    "tool_use": "tool_call",
    "stop_sequence": "stop",
}


def _map_finish(raw: str | None) -> str:
    if raw is None:
        return "unknown"
    return _FINISH_MAP.get(raw, "unknown")


def _convert_messages(request: GenerationRequest) -> tuple[str | None, list[dict[str, Any]]]:
    """Split GenerationRequest into system prompt + messages list for Anthropic API."""
    system: str | None = None
    messages: list[dict[str, Any]] = []
    for msg in request.messages:
        if msg.role == "system":
            system = msg.content or ""
        elif msg.role == "tool":
            # Tool result message
            messages.append(
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": msg.tool_call_id or "",
                            "content": msg.content or "",
                        }
                    ],
                }
            )
        elif msg.role == "assistant" and msg.tool_calls:
            # Assistant message with tool calls
            content: list[dict[str, Any]] = []
            if msg.content:
                content.append({"type": "text", "text": msg.content})
            for tc in msg.tool_calls:
                content.append(
                    {
                        "type": "tool_use",
                        "id": tc.call_id,
                        "name": tc.name,
                        "input": tc.arguments,
                    }
                )
            messages.append({"role": "assistant", "content": content})
        else:
            messages.append({"role": msg.role, "content": msg.content or ""})
    return system, messages


def _extract_tool_calls(response_content: list[Any]) -> list[ToolCall]:
    """Extract ToolCall objects from Anthropic response content blocks."""
    calls = []
    for block in response_content:
        if getattr(block, "type", None) == "tool_use":
            calls.append(
                ToolCall(
                    call_id=block.id,
                    name=block.name,
                    arguments=block.input or {},
                )
            )
    return calls


def _extract_text(response_content: list[Any]) -> str:
    """Extract concatenated text from Anthropic response content blocks."""
    parts = []
    for block in response_content:
        if getattr(block, "type", None) == "text":
            parts.append(block.text)
    return "".join(parts)


class AnthropicEngine:
    """
    LLM engine backed by the Anthropic API.

    Args:
        model:      Anthropic model identifier, e.g. "claude-sonnet-4-6".
        api_key:    API key. Defaults to ANTHROPIC_API_KEY env var.
        max_tokens: Default max tokens for generation (required by Anthropic API).
        timeout:    Request timeout in seconds.
        debug:      If True, preserve raw provider payload in responses.
    """

    # Signals to FailoverEngine that cloud data policy should be applied
    is_cloud: bool = True

    def __init__(
        self,
        model: str = "claude-sonnet-4-6",
        api_key: str | None = None,
        max_tokens: int = 1024,
        timeout: float = 60.0,
        debug: bool = False,
    ) -> None:
